def _activate():
    if state["active"]:
        return
    unsubscribers: list[Callable[[], None]] = []
    try:
        unsubscribers = setup_subscriptions() or []
    except Exception:
        # Keep state inactive so a future activate can retry.
        raise
    state["unsubscribers"] = list(unsubscribers)
    state["active"] = True
